update public.learning_paths
set
  title = 'Statistics for Criminal Justice',
  goal = 'Statistics for Criminal Justice',
  summary = 'The syllabus below is organized around official data systems, research design, responsible inference, applied modeling, reproducible analysis, and policy communication.',
  data = $stcjjson${"slug": "statistics-for-criminal-justice", "title": "Statistics for Criminal Justice", "description": "The syllabus below is organized around official data systems, research design, responsible inference, applied modeling, reproducible analysis, and policy communication.", "topics": [{"id": "ce557b42-b090-4b8f-b184-976e11fed837", "type": "topic", "title": "Criminal Justice Statistics, Data Literacy, and Evidence-Based Policy", "description": "Why statistics matter for policing, courts, corrections, victimization, reform, and public accountability.", "children": [{"id": "d28c8f6a-7502-4b73-9e76-3e335b1a4e2c", "type": "subtopic", "title": "Statistics as public evidence", "children": [{"id": "04d48f4d-1ff7-4d82-9efe-31d024811abd", "type": "concept", "title": "Distinguishing evidence from anecdote"}, {"id": "b7c6d1f1-40c6-4567-84cb-676f6f959d38", "type": "concept", "title": "Policy questions statistics can and cannot answer"}, {"id": "84b411ae-58b1-45de-b46c-14f6e7a5696b", "type": "concept", "title": "Using statistics for accountability"}], "description": "Students learn that criminal justice statistics are tools for judging claims about safety, fairness, effectiveness, and institutional performance."}, {"id": "f1180b06-9b4c-4f66-8a8c-ac717baa818d", "type": "subtopic", "title": "The American justice data ecosystem", "children": [{"id": "46c46904-8dd0-4120-b624-d71655896e73", "type": "concept", "title": "Police-reported crime"}, {"id": "19360e46-ead9-4ab1-a5ca-be2f23021e30", "type": "concept", "title": "Victimization and self-report data"}, {"id": "1de96081-1cb0-4afe-962e-4ca5a9265695", "type": "concept", "title": "Court and corrections records"}], "description": "This subtopic orients students to police, court, corrections, victimization, and administrative data as separate but connected evidence streams."}, {"id": "21443331-24a7-48f6-b63e-fa2e9cac8611", "type": "subtopic", "title": "Statistical reasoning habits", "children": [{"id": "3dcc5910-95a0-4a00-9a35-db19a18e0d2c", "type": "concept", "title": "Ask what is counted"}, {"id": "2784586b-f5c4-4545-9f08-c3541af46e66", "type": "concept", "title": "Ask who is missing"}, {"id": "81038683-2111-4452-bd45-392987fa9b52", "type": "concept", "title": "Ask what comparison is fair"}], "description": "The goal is to build habits of skepticism, precision, and transparency before formulas appear."}]}, {"id": "e2153ff6-d97a-4ebf-93df-83658aa99664", "type": "topic", "title": "Measurement, Operationalization, Variables, and Data Quality", "description": "How justice concepts become analyzable variables and where data quality can distort conclusions.", "children": [{"id": "601ca005-d63a-414a-b362-6ece047b032a", "type": "subtopic", "title": "Concepts to variables", "children": [{"id": "77c2ebc6-741c-42a5-98e3-e46431d5f6e4", "type": "concept", "title": "Constructs and indicators"}, {"id": "80970dcd-14b9-4070-bb75-80b6fa5d6a41", "type": "concept", "title": "Nominal, ordinal, interval, and ratio variables"}, {"id": "9b5dbe4b-5e16-4a3f-8a43-54256dadefab", "type": "concept", "title": "Dependent, independent, and control variables"}], "description": "Students learn how broad justice ideas such as crime, disorder, risk, harm, and recidivism become measurable variables."}, {"id": "a036e896-2e57-4b0e-937a-98cee93170f4", "type": "subtopic", "title": "Operational definitions", "children": [{"id": "185d03a0-361b-4810-b2f3-c750d250a78f", "type": "concept", "title": "Legal definitions versus survey definitions"}, {"id": "7f577156-74d1-4bf8-96cf-9950f0df4f66", "type": "concept", "title": "Unit of analysis"}, {"id": "a1395e13-e715-4ee2-a45a-6b64be7fa587", "type": "concept", "title": "Observation windows and follow-up periods"}], "description": "The point is to see that definitions drive results, especially for offenses, arrests, clearances, victimization, and program outcomes."}, {"id": "95c02e52-ec8c-4a79-956d-bad5201c7652", "type": "subtopic", "title": "Data quality and validity", "children": [{"id": "35f6ec6c-48e5-4bd1-8b85-b4adf5b6744f", "type": "concept", "title": "Reliability and validity"}, {"id": "6cdc151c-2c47-4e79-8614-4ad3532b3efc", "type": "concept", "title": "Missingness and nonresponse"}, {"id": "f88b78f4-3825-4a41-b4b7-90f7b3ecb3a4", "type": "concept", "title": "Administrative incentives and reporting bias"}], "description": "Students learn to diagnose measurement error before trusting a table or model."}]}, {"id": "4bfe1e77-b817-4dd2-a426-97b8ed17a8cf", "type": "topic", "title": "Crime Data Systems: UCR/NIBRS, NCVS, BJS, Courts, Corrections, and Administrative Data", "description": "Major American justice data systems, what each measures, and what each misses.", "children": [{"id": "17de241b-bfe2-4917-8357-ac3d3ef2ab12", "type": "subtopic", "title": "UCR and NIBRS", "children": [{"id": "faaf65f5-8256-458c-8f37-a1e02e07de1d", "type": "concept", "title": "Offense definitions"}, {"id": "0553614d-9e42-46ce-8d71-86498c1bef0e", "type": "concept", "title": "Agency participation and coverage"}, {"id": "9ff5805d-205d-42d3-b44e-04031dbad9fd", "type": "concept", "title": "Incident-level versus summary reporting"}], "description": "Students learn how police-reported crime data are collected and why incident-based data change what analysts can ask."}, {"id": "b55eaa06-44af-4230-b6d2-bad96f2b5a26", "type": "subtopic", "title": "NCVS and victimization surveys", "children": [{"id": "32967dbe-920e-459b-8152-da93eed69efa", "type": "concept", "title": "Reported versus unreported crime"}, {"id": "235ff9b4-6e40-447c-a8d1-a4af7ea668d4", "type": "concept", "title": "Survey sampling and weights"}, {"id": "2d080a7f-c315-4d6f-8c00-537533839581", "type": "concept", "title": "Recall and response error"}], "description": "The gist is that victimization surveys reveal experiences that never enter police records."}, {"id": "652de59c-3d20-430e-a840-6da27279fbf5", "type": "subtopic", "title": "Justice-system administrative data", "children": [{"id": "d440dbba-d7a6-4ddf-afba-76cb29c6db7e", "type": "concept", "title": "Caseload and disposition data"}, {"id": "c7e0c765-5fc6-4301-a8ec-9c702ae422aa", "type": "concept", "title": "Custody and supervision records"}, {"id": "c9e0849d-5c13-49af-b6e1-0f6f0a087177", "type": "concept", "title": "Linkage across agencies"}], "description": "Students learn how courts, jails, prisons, probation, parole, and case-management systems generate data for analysis."}]}, {"id": "f5f752be-052a-4927-a0be-30c3dff0d307", "type": "topic", "title": "Research Design, Sampling, Surveys, and Ethics in Justice Data", "description": "How to design defensible CJ studies and protect people represented in data.", "children": [{"id": "743ed9fe-9cc1-4c04-bd09-3be49a54b684", "type": "subtopic", "title": "Research questions and designs", "children": [{"id": "66561651-6413-451f-b542-682c94fa18c5", "type": "concept", "title": "Descriptive, explanatory, predictive, and evaluative questions"}, {"id": "b83e88ba-1e92-48eb-948c-a2103e2d15d7", "type": "concept", "title": "Cross-sectional and longitudinal designs"}, {"id": "b731a145-ada2-414d-84cd-fc5fc086c646", "type": "concept", "title": "Experiments and quasi-experiments"}], "description": "Students learn to match a question to an appropriate design instead of choosing a statistic first."}, {"id": "d3933cfc-318e-43dd-bab5-52fae39cf49a", "type": "subtopic", "title": "Sampling and survey design", "children": [{"id": "88dd9358-630a-40de-ab25-4c2586d84e43", "type": "concept", "title": "Target population and sampling frame"}, {"id": "c1c17300-377a-4739-abce-bf967867cecd", "type": "concept", "title": "Probability and nonprobability samples"}, {"id": "aa960a45-6907-4b44-a725-4a8e25912d5e", "type": "concept", "title": "Survey mode, wording, and nonresponse"}], "description": "This subtopic explains how samples represent populations and how design choices affect uncertainty."}, {"id": "18ad5ea2-b462-4939-9720-83fba1d45b7e", "type": "subtopic", "title": "Ethics and human subjects", "children": [{"id": "af82c49b-c4ae-402d-a1c9-19c547030d3c", "type": "concept", "title": "Confidentiality and disclosure risk"}, {"id": "7c70f17a-c5f9-4b4e-9b74-45639b40cd83", "type": "concept", "title": "IRB and informed consent basics"}, {"id": "2b382607-5de3-4585-b873-af6ccbb0288f", "type": "concept", "title": "Harm-aware reporting"}], "description": "Justice data often involve vulnerable people, state power, and sensitive records, so ethics is part of method rather than an add-on."}]}, {"id": "8f66625b-e895-42a5-8099-06057151a215", "type": "topic", "title": "Descriptive Statistics for Crime and Justice Data", "description": "Counts, rates, distributions, and summary statistics for justice questions.", "children": [{"id": "a0ec2172-4f3e-4b97-b944-038d1f091fb9", "type": "subtopic", "title": "Counts, rates, and denominators", "children": [{"id": "a7953fb4-4d76-43d6-abd9-5a12102954c7", "type": "concept", "title": "Incidents and persons"}, {"id": "38e57c64-78fb-4852-983c-05bb35bbc346", "type": "concept", "title": "Population denominators"}, {"id": "81c752c4-fb30-42db-809b-5ca67cad375e", "type": "concept", "title": "Per-capita and per-100,000 rates"}], "description": "Students learn why rates are usually more informative than raw counts when places or groups differ in size."}, {"id": "dce940d5-033f-4876-a477-ed282381694a", "type": "subtopic", "title": "Center and spread", "children": [{"id": "06538fcf-60fe-4070-ba22-1586bb68b70b", "type": "concept", "title": "Mean, median, and mode"}, {"id": "318dea0a-b667-48c7-844a-bf5e22c46a39", "type": "concept", "title": "Range, variance, and standard deviation"}, {"id": "7557b23a-dbc7-4535-b166-a2d5a79973dc", "type": "concept", "title": "Percentiles and interquartile range"}], "description": "The point is to summarize distributions without hiding meaningful variation."}, {"id": "941fb926-7566-46af-929a-404355e33a12", "type": "subtopic", "title": "Distribution shape and outliers", "children": [{"id": "016d91fd-1166-4bcf-bc4a-22f606bea686", "type": "concept", "title": "Skewness and heavy tails"}, {"id": "3e8f5989-4638-4157-9417-8a32addd3a6f", "type": "concept", "title": "Outliers and leverage points"}, {"id": "4466b072-7125-48e5-94d4-457cf827be2f", "type": "concept", "title": "Interpreting zero-inflated data"}], "description": "Students learn to inspect whether a few places, cases, or time periods are driving conclusions."}]}, {"id": "8c946afa-3e07-4f09-9e05-7019b3362cbe", "type": "topic", "title": "Data Visualization, Dashboards, Tables, and Geographic Display", "description": "Visual methods for showing patterns, uncertainty, and place-based variation without misleading readers.", "children": [{"id": "2e3db7e7-dfef-4df5-a00a-6455ee76d55d", "type": "subtopic", "title": "Graph selection", "children": [{"id": "3b950e34-1038-47d6-81fb-de02f4e8ec34", "type": "concept", "title": "Bar charts and ordered categories"}, {"id": "74807db6-1be8-44d5-aedc-c32552bde43c", "type": "concept", "title": "Histograms and density plots"}, {"id": "0f8dd92a-119d-40a6-a8e2-9d3aa793a0ef", "type": "concept", "title": "Line charts and trend displays"}], "description": "Students learn to choose a visual form that fits the comparison being made."}, {"id": "72a8a517-5104-4fb2-afd5-6ec98531460b", "type": "subtopic", "title": "Tables and dashboards", "children": [{"id": "f5b8e95b-9de6-455c-86f9-8e016a798cbb", "type": "concept", "title": "Table titles and notes"}, {"id": "1016bd99-a281-40a4-994a-c2bd51280276", "type": "concept", "title": "Dashboard filters and context"}, {"id": "cc894b12-1bc2-4fd6-8aa9-cee6ce87ec42", "type": "concept", "title": "Color, scale, and annotation choices"}], "description": "The goal is to design displays that support decisions without oversimplifying the data."}, {"id": "71c871d4-98cf-4bcf-b562-b73a26193983", "type": "subtopic", "title": "Geographic display", "children": [{"id": "bbaf07b5-35c9-42e0-a78f-733c196da917", "type": "concept", "title": "Choropleths and rate maps"}, {"id": "1bc11910-aef1-422a-b93f-668b491445d3", "type": "concept", "title": "Hot spots and clustering"}, {"id": "e5108266-dce9-43a1-ad99-c1e79617d632", "type": "concept", "title": "Modifiable areal unit problem"}], "description": "Students learn the promise and risk of mapping crime and justice outcomes."}]}, {"id": "34c23ca3-c368-47c0-91d2-4598824e675e", "type": "topic", "title": "Probability, Distributions, Base Rates, and Risk", "description": "Probability foundations for thinking about rare events, risk scores, and justice decision-making.", "children": [{"id": "f024672d-45f2-47d5-9660-49255ac32bb5", "type": "subtopic", "title": "Probability foundations", "children": [{"id": "d503fac5-c8aa-456c-bc42-d2567339b77e", "type": "concept", "title": "Events and complements"}, {"id": "6b1a4a46-de6e-41bd-b0b2-b7bc7d14d098", "type": "concept", "title": "Conditional probability"}, {"id": "c338c243-e26c-4b19-9e0d-f767d36055f0", "type": "concept", "title": "Independence and dependence"}], "description": "Students learn probability as a language for uncertainty, not just a set of calculations."}, {"id": "ea05a6b5-a40a-432b-bd72-fd6db41d9172", "type": "subtopic", "title": "Common distributions", "children": [{"id": "6d5ac4dc-a372-47e1-a615-27db61147637", "type": "concept", "title": "Binomial counts"}, {"id": "a96360c6-1172-4394-ae98-1c0060cd13bf", "type": "concept", "title": "Poisson event rates"}, {"id": "1605d43e-e9f7-456e-83c7-92363bee33f8", "type": "concept", "title": "Normal approximation and when it fails"}], "description": "This subtopic connects distributions to realistic justice examples."}, {"id": "8d48a21d-2739-4d0a-a668-64b402c562c5", "type": "subtopic", "title": "Base rates and risk", "children": [{"id": "9104bf1a-6ea2-4b1c-a0ba-be8c29f07b1c", "type": "concept", "title": "False positives and false negatives"}, {"id": "e8c8ddc8-1549-4196-b59d-03a60cbb8356", "type": "concept", "title": "Sensitivity and specificity"}, {"id": "f577d250-b964-41a7-ac56-04e1bcb32717", "type": "concept", "title": "Predictive value in low-base-rate settings"}], "description": "Students learn why ignoring base rates can distort screening, prediction, and public claims about danger."}]}, {"id": "0be06028-8051-45b8-a932-432f5c15713b", "type": "topic", "title": "Sampling Distributions, Confidence Intervals, and Margin of Error", "description": "How samples support estimates of populations, uncertainty, and confidence.", "children": [{"id": "78aefee9-f0e5-4b9a-a3b4-17546c2f1496", "type": "subtopic", "title": "Sampling variability", "children": [{"id": "d2751bc7-f0ff-4e7e-9b82-59c3d3d0a2b5", "type": "concept", "title": "Statistics versus parameters"}, {"id": "3d0d52f8-68fb-43ea-b2a1-c9806b5da8f1", "type": "concept", "title": "Standard error"}, {"id": "91adfdf0-355c-4c93-82b1-8a1defeb8152", "type": "concept", "title": "Central limit theorem intuition"}], "description": "Students learn why different samples produce different estimates even when methods are sound."}, {"id": "8eb6662e-202a-463e-a25d-2f547fd7af3e", "type": "subtopic", "title": "Confidence intervals", "children": [{"id": "c757e0a3-dec9-4bf7-9e17-b31df4b096fb", "type": "concept", "title": "Intervals for means"}, {"id": "31a5ab8d-af15-4622-b325-a81d5ebf755f", "type": "concept", "title": "Intervals for proportions and rates"}, {"id": "e8736cd1-2230-493a-877c-2e2309b7d324", "type": "concept", "title": "Interpreting confidence correctly"}], "description": "The point is to communicate uncertainty around estimates instead of pretending a single number is exact."}, {"id": "ba8fd066-08dc-4887-8734-ed4e398bfdc1", "type": "subtopic", "title": "Margins of error and survey weights", "children": [{"id": "61312d7d-152e-4a48-a6e7-75c6fa4714f3", "type": "concept", "title": "Design effects"}, {"id": "13b5f77d-165a-432d-a21d-6a098f9d8e4f", "type": "concept", "title": "Weighted estimates"}, {"id": "fb9836e4-2c95-4cc3-927f-33905b7fdd27", "type": "concept", "title": "Small subgroup cautions"}], "description": "Students learn how survey design affects uncertainty and representation."}]}, {"id": "3a102637-9ed8-421a-9507-91935e7f5e05", "type": "topic", "title": "Hypothesis Testing, Statistical Significance, and Practical Significance", "description": "How to test claims while separating statistical, practical, and ethical importance.", "children": [{"id": "7c66482d-6fa0-433a-b35e-f1d5fa757f91", "type": "subtopic", "title": "Logic of hypothesis testing", "children": [{"id": "ade0e897-93dc-4db2-9a8e-54ed40ab686e", "type": "concept", "title": "Null and alternative hypotheses"}, {"id": "cad6c742-dc2f-403f-899c-a91924e6ef0f", "type": "concept", "title": "Test statistics"}, {"id": "8a785a56-f279-49b4-bffb-d6eb73ef92c8", "type": "concept", "title": "p-values"}], "description": "Students learn how tests evaluate whether observed differences are surprising under a null model."}, {"id": "c2e27832-dd4f-4089-976d-849912ef4447", "type": "subtopic", "title": "Errors and power", "children": [{"id": "36c82390-84e8-4237-a02a-b589f1e9de86", "type": "concept", "title": "Type I and Type II errors"}, {"id": "72081fb5-c10b-42e0-95cf-59a178520a83", "type": "concept", "title": "Statistical power"}, {"id": "fd9b781b-557d-44cd-96c8-d5ad05ac0725", "type": "concept", "title": "Sample size and effect size"}], "description": "The aim is to understand the risks of overclaiming and underdetecting effects."}, {"id": "276a8334-5c4c-4ec6-83f2-c3467bbe11ab", "type": "subtopic", "title": "Practical and ethical significance", "children": [{"id": "ae7ddd7b-3bde-47d2-8699-b6c8bbfd70fc", "type": "concept", "title": "Effect sizes"}, {"id": "ab02c1f4-2f90-4bee-b9a0-b8e044f3eda6", "type": "concept", "title": "Confidence intervals alongside p-values"}, {"id": "5f400f75-5f25-436f-9136-3983439917bf", "type": "concept", "title": "Policy relevance and human stakes"}], "description": "Students learn that statistically detectable does not automatically mean important or just."}]}, {"id": "8b2f05e9-c246-474d-958d-fdecf22a7b2a", "type": "topic", "title": "Group Comparisons: Cross-Tabulation, Chi-Square, t-Tests, and ANOVA", "description": "Tools for comparing outcomes across places, groups, agencies, and interventions.", "children": [{"id": "8523ffa7-6ed1-44d0-909b-0feb062c72fb", "type": "subtopic", "title": "Cross-tabulation", "children": [{"id": "86f61689-07d1-46e0-9df4-b244599bf8b8", "type": "concept", "title": "Row and column percentages"}, {"id": "df64672a-1781-4f1d-91f0-93373eb1f9bf", "type": "concept", "title": "Expected counts"}, {"id": "66ef9919-042d-4b6e-9cc0-6b6e43be2617", "type": "concept", "title": "Interpreting conditional percentages"}], "description": "Students learn to compare categorical variables such as arrest status, charge type, sentence category, or program completion."}, {"id": "2c8a961a-6a0b-495c-ad6d-babbe2d1efb7", "type": "subtopic", "title": "Chi-square tests", "children": [{"id": "7dc461f8-cbeb-480a-b327-29e67777a790", "type": "concept", "title": "Goodness-of-fit"}, {"id": "dcb64202-164e-4923-87e2-cce70041366b", "type": "concept", "title": "Test of independence"}, {"id": "b16eb40d-9361-4d3c-86c5-cc087ccb8da2", "type": "concept", "title": "Assumptions and sparse cells"}], "description": "This subtopic gives students a core method for testing association between categorical variables."}, {"id": "8a2fac75-d5b3-4aa0-a952-4f67543735b7", "type": "subtopic", "title": "Mean comparisons", "children": [{"id": "f75191ce-6b2a-47b7-9dc8-bddca340107d", "type": "concept", "title": "Independent and paired t-tests"}, {"id": "97f06690-d590-43ef-a71d-3af211546237", "type": "concept", "title": "One-way ANOVA"}, {"id": "f5f1de9d-1a96-4223-9e76-77ceeeb8f804", "type": "concept", "title": "Post-hoc comparisons and assumptions"}], "description": "Students learn when to use t-tests or ANOVA for continuous outcomes such as sentence length, response time, or risk scores."}]}, {"id": "c8c9e8c8-c9f9-4f37-9af5-a6e9d5022203", "type": "topic", "title": "Association and Prediction: Correlation, Simple Regression, and Multiple Regression", "description": "How variables move together, how prediction works, and why association is not causation.", "children": [{"id": "0687bc4a-36b9-4063-9f18-7d7ef46a4e9c", "type": "subtopic", "title": "Correlation", "children": [{"id": "d27aa42e-4d94-4e88-9452-c5afce1af944", "type": "concept", "title": "Direction and strength"}, {"id": "d1aa9014-44a8-4cca-ba4e-1f734e83ccbc", "type": "concept", "title": "Scatterplots"}, {"id": "97e0c18e-74c9-4537-9272-7d9263e34028", "type": "concept", "title": "Outliers and nonlinear patterns"}], "description": "Students learn to measure linear association while recognizing that correlation is not causation."}, {"id": "b727dfc0-4e2d-428c-a4c4-d337f239a0c8", "type": "subtopic", "title": "Simple regression", "children": [{"id": "aaa41f03-e82b-4ec1-9442-b21ca6ca9aae", "type": "concept", "title": "Slope and intercept"}, {"id": "06bb04b6-e124-4f6f-81d9-6dd9e69a6967", "type": "concept", "title": "Residuals"}, {"id": "b118e0b1-87db-46eb-9922-293853b7bd6a", "type": "concept", "title": "R-squared"}], "description": "This subtopic introduces regression as a way to estimate and predict a numeric outcome from one predictor."}, {"id": "108cebab-5f1c-40f9-84d2-81581ae37687", "type": "subtopic", "title": "Multiple regression", "children": [{"id": "2af594f3-4832-476f-8591-810727c6140b", "type": "concept", "title": "Control variables"}, {"id": "d3c28694-cb57-46e6-b3f8-25ec7e3e46b5", "type": "concept", "title": "Confounding and omitted variables"}, {"id": "783d6425-b1d8-4d3c-b9b6-e106204c973e", "type": "concept", "title": "Diagnostics and multicollinearity"}], "description": "Students learn how controls change interpretation and why model assumptions matter."}]}, {"id": "69a55360-4788-4f77-a84d-4ddb671df97e", "type": "topic", "title": "Categorical Outcomes: Logistic Regression, Odds Ratios, and Classification", "description": "Methods for binary and categorical justice outcomes such as arrest, detention, conviction, revocation, and recidivism.", "children": [{"id": "6ad8fefd-72d9-4511-9679-750cd1f7ed8b", "type": "subtopic", "title": "Binary outcomes", "children": [{"id": "37d73e91-c35c-4051-89d9-5f239703c46d", "type": "concept", "title": "Arrest versus no arrest"}, {"id": "95c3223b-2a57-42a0-89eb-050aa522af1b", "type": "concept", "title": "Conviction versus acquittal"}, {"id": "8563f820-c83d-48cb-af72-2cc68a1182de", "type": "concept", "title": "Recidivism or revocation indicators"}], "description": "Many CJ outcomes are yes/no, so students learn methods built for categorical dependent variables."}, {"id": "2f9b4220-4c6e-4f03-91f3-6619bd87f16a", "type": "subtopic", "title": "Logistic regression", "children": [{"id": "e173294a-7ca9-4bf3-81d7-3d8746bbe28c", "type": "concept", "title": "Log odds and odds ratios"}, {"id": "f3e3ffd8-b716-43a7-b7e4-dc2c43c0d21c", "type": "concept", "title": "Predicted probabilities"}, {"id": "e060f0ed-4b6f-4b41-8c69-9c3a289eef74", "type": "concept", "title": "Model fit and interpretation"}], "description": "The point is to estimate associations for probabilities without using an inappropriate linear model."}, {"id": "08a9ccf0-d8ef-484b-aca6-544d73f67324", "type": "subtopic", "title": "Classification and errors", "children": [{"id": "ce60d640-dc64-466a-9fc4-afdb5077c12a", "type": "concept", "title": "Confusion matrices"}, {"id": "3a5f32ac-6379-45cb-b012-d84d86fe7d55", "type": "concept", "title": "Precision, recall, and specificity"}, {"id": "2530be3c-6c8e-4b1c-ab5a-be2ed5e0ac7d", "type": "concept", "title": "Threshold choice and fairness concerns"}], "description": "Students learn to evaluate predictive systems using accuracy measures that reveal tradeoffs."}]}, {"id": "076e3a80-8e6a-43c0-976a-520bffea4161", "type": "topic", "title": "Time, Place, and Trends: Rates, Seasonality, Time Series, and Crime Mapping", "description": "Analyzing crime trends over time and across geography with denominators and uncertainty.", "children": [{"id": "2a4b3870-7d54-42c8-a885-0e805761984b", "type": "subtopic", "title": "Trend analysis", "children": [{"id": "ede1df24-8aad-426e-8101-eedeb9dcfbbc", "type": "concept", "title": "Indexing and rate changes"}, {"id": "03db7bf5-b922-4388-a70f-8399ea4c7a89", "type": "concept", "title": "Rolling averages"}, {"id": "42e9104c-9745-458d-8be9-5b241b3a5aec", "type": "concept", "title": "Seasonality and cyclical patterns"}], "description": "Students learn to distinguish real changes from noise, reporting changes, and population shifts."}, {"id": "8c82d65c-3bed-4999-8243-98fb898a6299", "type": "subtopic", "title": "Place-based analysis", "children": [{"id": "1ff463c3-5b9b-4e6c-908b-9e2c1009dba3", "type": "concept", "title": "Spatial units"}, {"id": "ebbc7ca6-3eb4-47a2-8aa9-1f812579d717", "type": "concept", "title": "Exposure and opportunity"}, {"id": "40219712-fe47-47ae-b31d-d1ba2d931006", "type": "concept", "title": "Comparing places responsibly"}], "description": "This subtopic connects statistical reasoning to neighborhoods, beats, counties, and jurisdictions."}, {"id": "ebfb7c88-4ec4-450a-b378-675caedf4ece", "type": "subtopic", "title": "Mapping and public communication", "children": [{"id": "022d7d5c-ab2c-4d89-8c41-ed55afa210c7", "type": "concept", "title": "Classification choices"}, {"id": "92e30b8c-14f2-481e-a1b0-88be8d73cb2e", "type": "concept", "title": "Small-area instability"}, {"id": "061fe839-b801-4140-ad52-ac8cabfc77fc", "type": "concept", "title": "Privacy and stigmatization risks"}], "description": "Students learn how maps can clarify patterns or create false certainty."}]}, {"id": "c0f109ef-a797-4290-838f-c8df27de4cd0", "type": "topic", "title": "Program Evaluation, Causal Inference, and Evidence-Based Criminal Justice", "description": "Estimating whether policies and programs caused outcomes, not just whether outcomes changed.", "children": [{"id": "ace17f83-bde2-41a5-ab30-1b99518c2ab9", "type": "subtopic", "title": "Evaluation questions", "children": [{"id": "3042a1b3-3def-4c2d-8fca-6dc22b5cb953", "type": "concept", "title": "Process, outcome, and impact evaluation"}, {"id": "e57b8be9-3749-42d4-998a-5dbeabe982f9", "type": "concept", "title": "Logic models"}, {"id": "f5dc177c-1432-408d-ba67-c583d99803af", "type": "concept", "title": "Implementation fidelity"}], "description": "Students learn how to define success for interventions such as diversion, reentry, policing, courts, or treatment programs."}, {"id": "cd69a524-c4b7-4c1d-84db-298af9355ef5", "type": "subtopic", "title": "Causal designs", "children": [{"id": "9ae2d9db-8445-4b73-a2ab-909b2a7967fd", "type": "concept", "title": "Randomized experiments"}, {"id": "be761619-bf23-4a78-ba5d-7c15bcdc8461", "type": "concept", "title": "Matching and comparison groups"}, {"id": "7f92fa0f-2629-4732-a577-cfaf7e5bbf7f", "type": "concept", "title": "Difference-in-differences and regression discontinuity"}], "description": "The goal is to estimate what would have happened without the program or policy."}, {"id": "70aa1088-65e5-4778-90f0-07e0d5b4381f", "type": "subtopic", "title": "Evidence standards", "children": [{"id": "5ec98f90-25cd-44e0-8506-8e638c7f40d9", "type": "concept", "title": "Internal and external validity"}, {"id": "07492c28-5338-490b-90a2-8e5e542ebd25", "type": "concept", "title": "Threats to causal inference"}, {"id": "8c9b729c-9b8e-4e80-bd57-5ee9f36a700e", "type": "concept", "title": "Translating evidence into policy"}], "description": "Students learn how to read research claims and evidence ratings critically."}]}, {"id": "2c554750-2a48-4023-a732-3806541bf430", "type": "topic", "title": "Disparities, Equity, Bias, Missing Data, and Responsible Interpretation", "description": "Responsible analysis of racial, ethnic, gender, neighborhood, and institutional disparities.", "children": [{"id": "1881fedd-7d75-44e0-a17c-f4c4f1cf3a11", "type": "subtopic", "title": "Disparity measurement", "children": [{"id": "11b43ed0-acfd-466a-a7b8-5b9e6d3a20b1", "type": "concept", "title": "Absolute and relative differences"}, {"id": "