  ('ce557b42-b090-4b8f-b184-976e11fed837', 'd3e4f5a6-7b8c-4e43-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Criminal Justice Statistics, Data Literacy, and Evidence-Based Policy', 'Why statistics matter for policing, courts, corrections, victimization, reform, and public accountability.', 0),
  ('d28c8f6a-7502-4b73-9e76-3e335b1a4e2c', 'd3e4f5a6-7b8c-4e43-8f23-4a5b6c7d8e33', 'ce557b42-b090-4b8f-b184-976e11fed837', 'subtopic'::public.curated_course_node_type, 'Statistics as public evidence', 'Students learn that criminal justice statistics are tools for judging claims about safety, fairness, effectiveness, and institutional performance.', 0),
